mapper.select:
select af.af_id as afId, af.tel_id as telId, af.province_id as provinceId, af.city_id as cityId, af.address as address, af.information as information, af.estimated_grade as estimatedGrade, af.af_date as afDate, af.af_time as afTime, af.gm_id as gmId, af.assign_date as assignDate, af.assign_time as assignTime, af.state as state, af.remarks as remarks, p.province_name as provinceName, c.city_name as cityName, a.aqi_explain as aqiExplain, a.chinese_explain as chineseExplain, a.color as color, s.real_name as realName from aqi_feedback af left join grid_province p on af.province_id = p.province_id left join grid_city c on af.city_id = c.city_id left join aqi a on af.estimated_grade = a.aqi_id left join supervisor s on af.tel_id = s.tel_id
af.province_id = #{provinceId}
and af.city_id = #{cityId}
and af.estimated_grade = #{estimatedGrade}
and af.af_date like concat('%',#{afDate},'%')
order by af.af_id desc

mapper.update:
update aqi_feedback
set gm_id = #{gmId}, assign_date = #{assignDate}, assign_time = #{assignTime}, state = #{state}
where af_id = #{afId}
